{
  "tests": [
    "assert replacement_template('$&', 'hello world', (6, 11), []) == 'world'",
    "assert replacement_template('before $` after', 'hello world', (6, 11), []) == 'before hello after'",
    "assert replacement_template('before $' after', 'hello world', (6, 11), []) == 'before $ after'",
    "assert replacement_template('$1$2', 'hello world', (6, 11), ['foo', 'bar']) == 'foobar'",
    "assert replacement_template('no match here', 'hello world', (6, 11), []) == 'no match here'"
  ]
}

{
  "tests": [
    "assert single_defcom_extract(0, ['def example():', '    """This is a docstring."""', '    pass']) == '    """This is a docstring."""'",
    "assert single_defcom_extract(1, ['class MyClass:', '    def my_method(self):', '        '''Method docstring.'''', '        pass']) == '        '''Method docstring.''''",
    "assert single_defcom_extract(2, ['def another_function():', '    # This is a comment', '    pass']) == ''",
    "assert single_defcom_extract(0, ['"""Module level docstring."""', 'def func_with_module_doc():', '    pass']) == '"""Module level docstring."""'",
    "assert single_defcom_extract(3, ['class AnotherClass:', '    def __init__(self):', '        '''Constructor docstring.'''', '        self.value = 0']) == '        '''Constructor docstring.''''"
  ]
}

